create extension if not exists pgcrypto;
create type public.user_role as enum ('user','staff','admin'); create type public.case_kind as enum ('emergency','complaint'); create type public.case_status as enum ('received','under_review','assigned','in_progress','resolved','rejected'); create type public.case_priority as enum ('low','normal','high','critical');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,student_id text,faculty text,role public.user_role not null default 'user',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.agencies(id uuid primary key default gen_random_uuid(),name text not null,phone text,email text,description text,is_active boolean not null default true);
create table public.cases(id uuid primary key default gen_random_uuid(),tracking_code text unique not null,reporter_id uuid references public.profiles(id) on delete set null,case_kind public.case_kind not null,title text not null,category text not null,description text not null,phone text not null,location_name text,location_detail text,latitude double precision,longitude double precision,priority public.case_priority not null default 'normal',status public.case_status not null default 'received',assigned_agency_id uuid references public.agencies(id),assigned_staff_id uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table public.case_status_history(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases(id) on delete cascade,status public.case_status not null,note text,updated_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.case_attachments(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.cases(id) on delete cascade,file_path text not null,file_name text not null,mime_type text not null,file_size integer not null,uploaded_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.announcements(id uuid primary key default gen_random_uuid(),title text not null,content text not null,published_at timestamptz, is_published boolean not null default false,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,case_id uuid references public.cases(id) on delete cascade,title text not null,message text not null,is_read boolean not null default false,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index cases_tracking_code_idx on public.cases(tracking_code); create index cases_reporter_idx on public.cases(reporter_id); create index cases_status_idx on public.cases(status); create index cases_kind_idx on public.cases(case_kind); create index cases_created_idx on public.cases(created_at desc); create index cases_agency_idx on public.cases(assigned_agency_id); create index cases_staff_idx on public.cases(assigned_staff_id);
create or replace function public.is_staff_or_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('staff','admin')); $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create or replace function public.create_case(p_reporter_id uuid,p_case_kind public.case_kind,p_title text,p_category text,p_description text,p_phone text,p_location_name text,p_location_detail text,p_latitude double precision,p_longitude double precision) returns text language plpgsql security definer set search_path=public as $$ declare seq bigint; code text; new_id uuid; prefix text; begin if p_reporter_id is not null and p_reporter_id<>auth.uid() then raise exception 'invalid reporter'; end if; prefix:=case when p_case_kind='emergency' then 'EMG' else 'KKU' end; perform pg_advisory_xact_lock(hashtext(prefix||to_char(now(),'YYYY'))); select coalesce(max((regexp_match(tracking_code,'(\\d+)$'))[1]::bigint),0)+1 into seq from public.cases where tracking_code like prefix||'-'||to_char(now(),'YYYY')||'-%'; code:=format('%s-%s-%s',prefix,to_char(now(),'YYYY'),lpad(seq::text,5,'0')); insert into public.cases(tracking_code,reporter_id,case_kind,title,category,description,phone,location_name,location_detail,latitude,longitude) values(code,p_reporter_id,p_case_kind,p_title,p_category,p_description,p_phone,p_location_name,p_location_detail,p_latitude,p_longitude) returning id into new_id; insert into public.case_status_history(case_id,status,updated_by) values(new_id,'received',auth.uid()); return code; end; $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,new.raw_user_meta_data->>'full_name','user'); return new; end; $$; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.cases enable row level security; alter table public.case_status_history enable row level security; alter table public.case_attachments enable row level security; alter table public.agencies enable row level security; alter table public.announcements enable row level security; alter table public.notifications enable row level security; alter table public.audit_logs enable row level security;
create policy profiles_self on public.profiles for select using(id=auth.uid() or public.is_admin()); create policy cases_read on public.cases for select using(reporter_id=auth.uid() or assigned_staff_id=auth.uid() or public.is_admin()); create policy cases_insert on public.cases for insert with check(reporter_id=auth.uid() or (reporter_id is null and case_kind='emergency')); create policy history_read on public.case_status_history for select using(exists(select 1 from cases c where c.id=case_id and (c.reporter_id=auth.uid() or c.assigned_staff_id=auth.uid() or public.is_admin()))); create policy agency_public on public.agencies for select using(is_active=true or public.is_staff_or_admin()); create policy announcements_public on public.announcements for select using(is_published=true or public.is_staff_or_admin()); create policy notifications_self on public.notifications for select using(user_id=auth.uid());
insert into public.agencies(name,phone) values ('กองป้องกันและรักษาความปลอดภัย มข.','043-202-191'),('กองอาคารและสถานที่','043-202-222'),('โรงพยาบาลศรีนครินทร์','1669'),('สถานีตำรวจภูธรเมืองขอนแก่น','191');
create policy cases_staff_update on public.cases for update using(assigned_staff_id=auth.uid() or public.is_admin()) with check(assigned_staff_id=auth.uid() or public.is_admin());
create policy history_staff_insert on public.case_status_history for insert with check(public.is_staff_or_admin() and exists(select 1 from cases c where c.id=case_id and (c.assigned_staff_id=auth.uid() or public.is_admin())));
create policy attachments_read on public.case_attachments for select using(exists(select 1 from cases c where c.id=case_id and (c.reporter_id=auth.uid() or c.assigned_staff_id=auth.uid() or public.is_admin())));
